with legs(i,player,market,n) as (values (3,'Luka Doncic','player_points',25),(4,'Luka Doncic','player_points',30),(5,'Luka Doncic','player_points_rebounds_assists',40),(6,'Daniss Jenkins','player_points',15),(7,'Daniss Jenkins','player_assists',8),(8,'Daniss Jenkins','player_assists',6),(9,'Julius Randle','player_assists',4),(10,'Jalen Johnson','player_rebounds',8),(11,'Brice Sensabaugh','player_rebounds',2),(12,'Brice Sensabaugh','player_assists',2),(13,'Rui Hachimura','player_points',10),(14,'Tyrese Maxey','player_points',25),(15,'Tyrese Maxey','player_points',20),(16,'Cooper Flagg','player_points_rebounds_assists',35),(17,'Cooper Flagg','player_points_rebounds_assists',30),(18,'Cooper Flagg','player_rebounds',6),(19,'Cooper Flagg','player_assists',6),(20,'Pascal Siakam','player_points',20),(21,'Zion Williamson','player_points_rebounds_assists',25),(24,'Josh Hart','player_rebounds',10),(25,'Josh Hart','player_assists',8),(26,'Ausar Thompson','player_rebounds',10),(27,'Ausar Thompson','player_rebounds',8),(28,'Ausar Thompson','player_assists',8),(29,'Ausar Thompson','player_assists',6),(30,'Victor Wembanyama','player_rebounds',12),(31,'Victor Wembanyama','player_rebounds',10),(32,'LeBron James','player_rebounds',6),(33,'LeBron James','player_assists',6),(34,'Quentin Grimes','player_assists',2),(40,'Joel Embiid','player_assists',4),(41,'Joel Embiid','player_assists',2),(42,'Donovan Clingan','player_rebounds',11),(43,'Donovan Clingan','player_rebounds',10),(44,'Donovan Clingan','player_rebounds',8),(45,'Tyler Herro','player_assists',5),(46,'Tyler Herro','player_assists',6),(47,'Cam Spencer','player_assists',5),(48,'Cam Spencer','player_assists',4),(49,'Draymond Green','player_assists',6),(50,'Draymond Green','player_assists',8),(51,'DeMar DeRozan','player_assists',4)),
nv as (select * from book_novig where pulled_at > now() - interval '2 hours'),
c as (select l.i, v.line, v.books, v.fair_over, row_number() over (partition by l.i order by (v.line = l.n - 0.5) desc, v.books desc, abs(v.fair_over-0.5)) rn
 from legs l join nv v on v.market=l.market and regexp_replace(regexp_replace(lower(v.player),'( jr\.?| sr\.?| iii| ii| iv)$',''),'[^a-z]','','g') = regexp_replace(regexp_replace(lower(l.player),'( jr\.?| sr\.?| iii| ii| iv)$',''),'[^a-z]','','g'))
select string_agg(i||':'||json_build_array(line,books,round(fair_over::numeric,4))::text, ';' order by i) from c where rn=1;